describe('Tablet Layout - Two Column Grid', () => {
  beforeEach(() => {
    cy.visit('/tablet-view');
  });

  it('should display two-column grid layout on tablet screen', () => {
    // Intercept API calls to verify data loading
    cy.intercept('GET', '/api/products').as('getProducts');
    cy.wait('@getProducts');

    // Verify the viewport is set to tablet size
    cy.viewport('ipad');

    // Verify the two-column grid is visible
    cy.get('[data-testid="product-grid"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Verify the grid has two columns
    cy.get('[data-testid="product-grid"]').should('have.css', 'grid-template-columns', '2');

    // Verify each item is displayed in a column
    cy.get('[data-testid="product-item"]').each(($item) => {
      cy.wrap($item).should('be.visible');
    });

    // Verify the layout is responsive and not stacked
    cy.get('[data-testid="product-item"]').first().should('not.have.css', 'width', '100%');
    cy.get('[data-testid="product-item"]').first().should('have.css', 'width', 'calc(50% - 16px)');
  });

  it('should handle edge case with empty product list on tablet', () => {
    // Intercept API call with empty response
    cy.intercept('GET', '/api/products', {
      statusCode: 200,
      body: { products: [] }
    }).as('getEmptyProducts');
    cy.wait('@getEmptyProducts');

    // Verify the viewport is set to tablet size
    cy.viewport('ipad');

    // Verify the grid container is visible
    cy.get('[data-testid="product-grid"]').should('be.visible');

    // Verify no product items are displayed
    cy.get('[data-testid="product-item"]').should('not.exist');

    // Verify an empty state message is shown
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No products found');

    // Verify the grid container has appropriate styling even when empty
    cy.get('[data-testid="product-grid"]').should('have.css', 'grid-template-columns', '2');
  });
});
